// flashcard drill — JAH Cloud Types Database (jahdb demo program)
var ITEMS=[["Cirrus","Wispy ice-crystal streaks high up; fair weather but a change may come."], ["Cirrocumulus","Tiny white ripples; a mackerel sky."], ["Cirrostratus","Thin veil making a halo around the sun or moon."], ["Altostratus","Gray-blue sheet dimming the sun like ground glass."], ["Altocumulus","White-gray patches in rolls or waves."], ["Nimbostratus","Thick dark rain sheet; steady precipitation."], ["Stratocumulus","Low lumpy rolls, sometimes breaking to blue."], ["Stratus","Flat gray blanket; drizzle and fog-like."], ["Cumulus humilis","Small fair-weather puffs."], ["Cumulus mediocris","Taller puffs with some vertical growth."], ["Cumulus congestus","Towering cauliflower; may grow into storms."], ["Cumulonimbus","The thunderstorm king: anvil top, lightning, hail."], ["Mammatus","Pouch-like udders hanging under storm clouds."], ["Altocumulus lenticularis","Lens-shaped UFO clouds over mountains."], ["Pileus","A smooth cap over a rising cumulus tower."], ["Virga","Rain streaks that evaporate before landing."], ["Cirrus uncinus","Hooked mare's tails."], ["Cirrostratus fibratus","Fibrous high veil."], ["Altocumulus castellanus","Turreted mid clouds; instability aloft."], ["Stratus fractus","Ragged scud racing under rain."], ["Cumulus fractus","Ragged shreds in wind."], ["Nimbostratus pannus","Ragged low scraps under the rain sheet."], ["Arcus","The shelf or roll cloud at a storm front."], ["Tuba","Funnel cloud; a tornado in the making or not."], ["Asperitas","Wild wave-like undulations; dramatic but not stormy."], ["Fluctus","Kelvin-Helmholtz breaking waves."], ["Cavum","A punch-hole in altocumulus, sometimes with virga."], ["Noctilucent","Electric-blue night-shining clouds near the poles in summer."], ["Nacreous","Mother-of-pearl polar stratospheric clouds."], ["Contrails","Jet exhaust ice trails; artificial cirrus."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
console.log("== drill ==");console.log(ask(5));

